{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core_dist[u], core_dist[v], d)
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {}
    rank = {}
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    for node in nodes:
        parent[node] = node
        rank[node] = 0
    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError("Graph is not connected; cannot compute MST")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
